3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** owner-segment: ownerSegment = '<TIER>_<AREA>'; TIER is STANDARD below membershipLevel 3,
8	 * AREA is METRO for a known region (NSW/VIC/QLD) else REGIONAL. A new owner with an email scores
9	 * membershipLevel 2 (STANDARD); a known city is METRO, an unknown city is REGIONAL. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreSegmentForKnownRegion() throws Exception {
14			ObjectNode o = knownOwner("Sydney"); // NSW
15			o.put("email", uniqueEmail()); // level 2 -> STANDARD
16			int id = createOwnerOk(o);
17			getOwner(id).andExpect(jsonPath("$.ownerSegment").value("STANDARD_METRO"));
18		}
19	
20		@Test
21		void functionalitySegmentForUnknownRegion() throws Exception {
22			ObjectNode o = ownerNode(); // random city -> UNKNOWN region -> REGIONAL
23			o.put("email", uniqueEmail());
24			int id = createOwnerOk(o);
25			getOwner(id).andExpect(jsonPath("$.ownerSegment").value("STANDARD_REGIONAL"));
26		}
27	}
